mapper.select:
SELECT 
FROM conversation_turn
WHERE conversation_id = #{conversationId}
  AND turn_no > #{afterTurnNo}
  AND status != #{processingStatus}
ORDER BY turn_no ASC

mapper.update:
UPDATE conversation_turn t
INNER JOIN agent_conversation c ON c.id = t.conversation_id
SET t.assistant_content = #{assistantContent},
    t.assistant_token_estimate = #{assistantTokenEstimate},
    t.final_model_call_id = #{finalModelCallId},
    t.compression_level = #{compressionLevel},
    t.status = #{successStatus},
    t.finish_time = #{finishTime}
WHERE t.id = #{turnId}
  AND t.status = #{processingStatus}
  AND c.execution_owner = #{leaseOwner}
  AND c.execution_epoch = #{executionEpoch}
  AND c.execution_expire_time >= #{currentTime}

UPDATE conversation_turn t
INNER JOIN agent_conversation c ON c.id = t.conversation_id
SET t.status = #{terminalStatus},
    t.error_code = #{errorCode},
    t.error_message = #{errorMessage},
    t.finish_time = #{finishTime}
WHERE t.id = #{turnId}
  AND t.status = #{processingStatus}
  AND c.execution_owner = #{leaseOwner}
  AND c.execution_epoch = #{executionEpoch}
  AND c.execution_expire_time >= #{currentTime}
